"""Deterministically replay one classified C1 branch; source certificates are generated by Box4's emitter."""
from pathlib import Path
from collections import Counter
from math import prod
from concurrent.futures import ThreadPoolExecutor
import argparse, json, os, shutil, subprocess, sys, time
HERE=Path(__file__).resolve().parent
from finish import domain_for,trace_long

def finish_trace(target):
    ds=domain_for(target);tag=str(target)
    stack=[tuple(map(int,l.split())) for l in open('hard'+tag+'.txt') if l.strip()]
    count=Counter();mass=sum(prod(len(ds[i]) for i,v in enumerate(t) if v<0) for t in stack)
    out=[];fails=[];holes=[];start=time.monotonic()
    while stack:
        t=stack.pop();r=trace_long(t,limit=16384,cycle_limit=2048);typ=r[0]
        if typ=='hole':
            i=r[2];holes.append([t,['hole',i]])
            stack.extend(t[:i]+(v,)+t[i+1:] for v in ds[i]);continue
        if typ in ('halt','cycle','side'):
            out.append([t,r]);count[typ]+=1
        else:fails.append([t,r]);count['hard']+=1
    assert sum(prod(len(ds[i]) for i,v in enumerate(t) if v<0) for t,_ in out+fails)==mass
    json.dump({'target':target,'out':out+holes,'fails':fails,'mass':mass,'counts':count},open(f'long{tag}.json','w'))
    with open(f'rlestart{tag}.txt','w') as f:
        for t,_ in fails:f.write(' '.join(map(str,t))+'\n')
    print(target,'long-trace',dict(count),'mass',mass,'seconds',round(time.monotonic()-start,2),flush=True)

def main():
    p=argparse.ArgumentParser();p.add_argument('c',type=int);p.add_argument('--target',type=int,choices=range(6,12));p.add_argument('--work')
    args=p.parse_args();cfg=json.loads((HERE/'branches.json').read_text())[str(args.c)]
    work=Path(args.work or f'/tmp/a13-box3-c{args.c}-replay').resolve()
    work.mkdir(parents=True,exist_ok=True);os.chdir(work)
    targets=[args.target] if args.target is not None else list(range(6,12))
    for pattern in ('open*.txt','ngram*.txt','hard*.txt','long*.json','tree*.txt','rlestart*.txt','rle*.txt','greedyboxes.*'):
        for stale in work.glob(pattern):stale.unlink()
    def call(*cmd):subprocess.run([str(x) for x in cmd],check=True)
    for n in ('scan','classify','rle_scan','treegen'):
        call('g++','-O3','-std=c++17',HERE/(n+'.cpp'),'-o',work/n)
    def discover(t):
        call(work/'scan',t);call(work/'classify',t);finish_trace(t);call(work/'rle_scan',t)
    with ThreadPoolExecutor(max_workers=4) as pool:list(pool.map(discover,targets))
    stack=[];block=[];remaining=[]
    for t in targets:
        for l in open(f'rle{t}.txt'):
            a=list(map(int,l.split()));assert len(a)==21
            stack.append([a[:12],a[12:16],a[16:20]])
        for l in open(f'rlehard{t}.txt'):
            a=list(map(int,l.split()));remaining.append(a)
    seeds={tuple(t):p for t,p in cfg['block']}
    for t in remaining:
        if tuple(t) not in seeds:raise ValueError(f'Unresolved leaf: {t}')
        block.append([t,seeds[tuple(t)]])
    # Reject stale or omitted seeds; target slices are independent.
    assert {tuple(t) for t,_ in block}=={t for t in seeds if t.index(0) in targets}
    (HERE/'survivors.json').write_text(json.dumps({'stack':stack,'block':block}))
    opt=[] if args.target is None else [str(args.target)]
    call(sys.executable,HERE/'greedy.py',*opt)
    for t in targets:call(work/'treegen',t)
    out=HERE/'generated';shutil.rmtree(out,ignore_errors=True)
    call(sys.executable,HERE/'emit_proof.py',out,*opt)
    print('source candidates generated:',args.c,targets,'RLE',len(stack),'block',len(block),flush=True)

if __name__=='__main__':main()
